    spec(8, "광고심사위원회", "변호사 광고 심사를 위하여 대한변호사협회와 각 지방변호사회에 광고심사위원회를 둔다.", "변호사 광고 심사는 대한변호사협회에서만 담당하고 지방변호사회에는 광고심사위원회를 두지 않는다.", "변호사업무광고규정", "심사위원회"),
    spec(8, "법무법인 광고 표시사항", "법무법인 광고에는 원칙적으로 명칭, 주소, 연락처를 표시하면 되고 대표 변호사 표시가 항상 필수는 아니다.", "법무법인 광고에는 원칙적으로 명칭, 주소, 연락처 외에 대표 변호사도 표시하여야 한다.", "변호사업무광고규정", "대표 변호사 표시", grade="A+"),
    spec(8, "직권 조사", "대한변호사협회 광고심사위원회 위원장은 광고규정 위반 여부를 심사 요청과 관계없이 직권으로 조사할 수 있다.", "대한변호사협회 광고심사위원회 위원장은 변호사의 심사 요청이 있어야만 광고규정 위반 여부를 조사할 수 있다.", "변호사업무광고규정", "직권 조사"),
    spec(8, "광고 질의", "광고 내용과 방법에 의문이 있으면 해당 변호사뿐만 아니라 이해관계자도 소속 지방변호사회 회장에게 서면 질의할 수 있다.", "광고 내용과 방법에 관한 질의는 해당 변호사만 할 수 있고 이해관계자는 질의할 수 없다.", "변호사업무광고규정", "이해관계자 질의"),

    spec(9, "비공개 정보 누설금지", "의뢰인이 공개를 원하지 않는 직무상 정보를 변호사가 알게 된 경우 이를 누설하지 않아야 한다.", "의뢰인이 공개를 원하지 않는 직무상 정보라도 변호사가 소송 중 알게 된 정보이면 자유롭게 누설할 수 있다.", "변호사법 제26조, 변호사윤리장전", "정보 누설"),
    spec(9, "공지사실", "변호사가 소송 중 알게 된 정보라도 공지의 사실이면 비밀유지의 대상이 되지 않는다.", "변호사가 소송 중 알게 된 정보는 공지의 사실이어도 비밀유지의 대상이 된다.", "변호사법 제26조", "공지 사실"),
    spec(9, "비밀 이용금지", "변호사는 의뢰인의 비밀을 누설하지 않더라도 그 비밀을 자신의 투자수익을 위해 이용하면 비밀유지의무와 충실의무에 위반될 수 있다.", "의뢰인의 비밀을 자신의 투자수익을 위해 이용하더라도 외부에 누설하지 않았다면 비밀유지의무 위반이 아니다.", "변호사법 제26조, 변호사윤리장전", "비밀 이용", grade="A+"),
    spec(9, "사무직원 자료정리", "변호사가 직무수행에 필요한 범위에서 비밀 관련 소송자료를 사무직원에게 정리하게 하는 것은 허용될 수 있다.", "변호사는 비밀 관련 소송자료를 어떠한 경우에도 사무직원에게 정리하게 할 수 없다.", "변호사법 제26조", "사무직원 공유"),

    spec(10, "변호사 의뢰인 특권", "현행법상 변호인과 의뢰인 사이 법률자문 목적 의사교환에 대한 일반적 증거거부 특권은 명문으로 인정되어 있지 않다.", "현행법상 헌법상 변호인의 조력을 받을 권리에서 의뢰인의 일반적 증거거부 특권이 당연히 인정된다.", "헌법, 형사소송법, 판례", "증거거부 특권"),
    spec(10, "법률의견서 증거능력", "변호사가 작성한 법률의견서도 압수절차가 적법하면 의뢰인 동의가 없다는 사정만으로 형사재판 증거사용이 당연히 배제되지는 않는다.", "변호사가 작성한 법률의견서는 의뢰인 동의가 없으면 압수절차 적법 여부와 관계없이 형사재판 증거로 사용할 수 없다.", "형사소송법, 판례", "법률의견서"),
    spec(10, "허위자백 유지", "진범 은폐를 위한 허위자백을 적극적으로 유지하게 하는 행위는 변호인의 비밀유지의무로 정당화될 수 없다.", "진범 은폐를 위한 허위자백을 적극적으로 유지하게 하는 행위도 변호인의 비밀유지의무로 정당화될 수 있다.", "형법, 변호사윤리장전", "허위자백", grade="A+"),
    spec(10, "직무자료 비공개", "변호사는 직무수행 중 작성한 서류, 메모, 기타 유사한 자료를 외부에 공개하지 않아야 한다.", "변호사는 직무수행 중 작성한 메모나 유사 자료는 공식 서류가 아니므로 외부에 공개할 수 있다.", "변호사윤리장전", "메모 비공개"),

    spec(11, "행정조사 의사교환", "공정거래위원회 조사·심의과정에서 이루어진 변호사와 의뢰인 사이의 의사교환도 비밀보호의 대상이 될 수 있다.", "공정거래위원회 조사·심의과정에서 이루어진 변호사와 의뢰인 사이의 의사교환은 비밀보호의 대상이 되지 않는다.", "변호사법 제26조", "행정조사 비밀", grade="A+"),
    spec(11, "증언 예정 사건 수임", "변호사는 본인이 제공한 법률사무 내용에 관하여 증언해야 하는 경우 그 사건을 수임할 수 있다.", "변호사는 본인이 제공한 법률사무 내용에 관하여 증언해야 하는 경우 그 사건을 수임할 수 없다.", "변호사법 제31조", "증언과 수임"),
    spec(11, "자기방어 공개", "변호사는 직무상 알게 된 의뢰인의 비밀이라도 자신의 권리를 방어하기 위하여 필요한 경우 최소한의 범위에서 공개할 수 있다.", "변호사는 자신의 권리를 방어하기 위해서도 의뢰인의 비밀을 공개할 수 없다.", "변호사윤리장전", "자기방어"),
    spec(11, "퇴직 후 비밀", "변호사 또는 변호사였던 사람은 직무상 알게 된 비밀을 누설해서는 안 되지만 법률에 특별한 규정이 있으면 예외가 인정될 수 있다.", "변호사였던 사람은 더 이상 변호사가 아니므로 직무상 알게 된 비밀을 누설하지 않을 의무가 없다.", "변호사법 제26조", "퇴직 후 비밀"),

    spec(12, "공익상 공개", "변호사는 직무상 알게 된 의뢰인의 비밀이라도 공익상 이유가 있을 때 제한 없이 공개할 수는 없다.", "변호사는 공익상 이유가 있으면 직무상 알게 된 의뢰인의 비밀을 제한 없이 공개할 수 있다.", "변호사법 제26조, 변호사윤리장전", "공익상 이유"),
    spec(12, "해임 후 비밀", "변호사는 해임된 뒤에도 업무처리 중 알게 된 의뢰인의 비밀을 공개할 수 없다.", "변호사는 해임된 뒤에는 업무처리 중 알게 된 의뢰인의 비밀을 공개할 수 있다.", "변호사법 제26조", "해임 후 비밀", grade="A+"),
    spec(12, "행정심판 서류제출", "변호사는 행정심판위원회가 의뢰인의 소송관련서류 제출을 요구하더라도 비밀유지의무가 문제되면 제출을 거절할 수 있다.", "변호사는 행정심판위원회가 의뢰인의 소송관련서류 제출을 요구하면 비밀유지의무와 관계없이 제출하여야 한다.", "행정심판법, 변호사법 제26조", "서류제출"),
    spec(12, "비밀유지 예외", "비밀유지의무는 절대적 의무가 아니지만 예외가 인정되더라도 필요한 최소한의 범위로 제한된다.", "비밀유지의무는 공익 또는 해임 등 사유가 있으면 전면적으로 소멸한다.", "변호사윤리장전", "예외 범위"),

    spec(13, "본안과 집행 의무", "본안소송 수임만으로 강제집행이나 보전처분에 관한 위임계약상 의무가 당연히 발생하지 않고 위임계약 내용에 따라 정해진다.", "본안소송을 수임하면 강제집행이나 보전처분에 관한 위임계약상 의무도 당연히 발생한다.", "민법, 판례", "본안과 집행"),
    spec(13, "독립 변호인 선임권", "피고인 또는 피의자의 법정대리인, 배우자, 직계친족과 형제자매는 독립하여 변호인을 선임할 수 있다.", "피고인 또는 피의자의 법정대리인, 배우자, 직계친족과 형제자매도 본인의 위임 없이는 변호인을 선임할 수 없다.", "형사소송법", "독립 선임권"),
    spec(13, "상소 설명의무", "패소판결에 계산상 잘못 등 불이익이 있으면 변호사는 특별수권이 없어도 상소 가능성 등을 설명하고 조언하여야 할 수 있다.", "패소판결이 있어도 상소에 관한 특별수권이 없으면 변호사는 상소 가능성을 설명할 의무가 없다.", "민법, 판례", "상소 조언"),
    spec(13, "일반적 모든 조치 의무", "변호사는 구체적 위임사무 범위를 넘어 의뢰인의 모든 재산상 권리 옹호 조치를 취할 일반적 의무를 부담하지 않는다.", "변호사는 구체적 위임사무 범위를 넘어 의뢰인의 재산 등 권리 옹호에 필요한 모든 조치를 취할 일반적 의무를 부담한다.", "민법, 판례", "일반 의무", grade="A+"),

    spec(14, "선관주의의무", "변호사는 의뢰인에 대하여 선량한 관리자의 주의로 법률사무를 처리하여야 한다.", "변호사는 독립 전문직이므로 의뢰인에 대하여 선량한 관리자의 주의의무를 부담하지 않는다.", "민법 제681조", "선관주의"),
    spec(14, "민사 성공보수", "부동산소유권이전등기청구사건에서 승소 등 일정 결과 발생을 조건으로 성공보수를 약정하는 것은 원칙적으로 허용될 수 있다.", "부동산소유권이전등기청구사건에서 승소 등 일정 결과 발생을 조건으로 성공보수를 약정하는 것은 사회상규에 반하여 위법하다.", "민법, 판례", "민사 성공보수", grade="A+"),
    spec(14, "사무직원 과실", "사무직원의 과실로 불변기간을 놓친 경우에도 변호사의 위임계약상 과실로 평가될 수 있다.", "사무직원의 과실로 불변기간을 놓친 경우에는 변호사 본인의 과실로 평가될 수 없다.", "민법, 판례", "사무직원 과실"),
    spec(14, "복위임", "변호사는 직접 사무처리하는 것이 원칙이나 의뢰인 승낙이나 부득이한 사유가 있으면 복위임이 허용될 수 있다.", "변호사는 자기 스스로 사무를 처리하여야 하므로 의뢰인 승낙이 있어도 복위임할 수 없다.", "민법 제682조", "복위임"),

    spec(15, "종전 사건 종료 후 별개 사건", "종전 상대방이던 사람이 별개의 양수금청구사건을 제기하는 경우 기존 의뢰인의 동의 없이도 수임이 가능한 경우가 있다.", "종전 상대방이던 사람이 별개의 양수금청구사건을 제기하는 경우 사건이 달라도 기존 의뢰인의 동의 없이는 수임할 수 없다.", "변호사법 제31조", "별개 사건"),
    spec(15, "현재 상대방 사건", "현재 진행 중인 사건의 상대방이 기존 의뢰인을 상대로 제기하는 사건은 기존 의뢰인의 동의 없이 수임하기 어렵다.", "현재 진행 중인 사건의 상대방이 기존 의뢰인을 상대로 제기하는 별개 청구는 언제나 기존 의뢰인의 동의 없이 수임할 수 있다.", "변호사법 제31조", "현재 상대방"),
    spec(15, "관련 형사사건", "현재 진행 중인 손해배상사건의 상대방이 같은 횡령 사실로 재판받는 형사사건은 기존 의뢰인의 이익과 충돌하여 수임제한이 문제된다.", "현재 진행 중인 손해배상사건의 상대방 형사사건은 절차가 다르므로 기존 의뢰인의 동의 없이 수임할 수 있다.", "변호사법 제31조", "관련 형사사건"),
    spec(15, "실질 동일 채무부존재", "소제기를 준비 중인 손해배상청구와 실질적으로 동일한 분쟁의 채무부존재확인 사건은 상대방 의뢰를 수임할 수 없다.", "소제기를 준비 중인 손해배상청구와 실질적으로 동일한 채무부존재확인 사건도 아직 소가 제기되지 않았으면 상대방 의뢰를 수임할 수 있다.", "변호사법 제31조", "실질 동일", grade="A+"),

    spec(16, "공동 등기신청", "부동산 매매계약의 매도인과 매수인으로부터 소유권이전등기신청을 공동 위임받아 대리하는 것은 허용될 수 있다.", "부동산 매매계약의 매도인과 매수인으로부터 소유권이전등기신청을 공동으로 위임받아 대리하는 것은 허용되지 않는다.", "변호사윤리장전", "공동신청", grade="A+"),
    spec(16, "배우자 사건", "배우자인 변호사가 수임하고 있는 사건의 대립 당사자 사건은 의뢰인의 동의가 있으면 수임이 허용될 수 있다.", "배우자인 변호사가 수임 중인 사건의 대립 당사자 사건은 의뢰인 동의가 있어도 수임할 수 없다.", "변호사윤리장전", "배우자 수임"),
    spec(16, "이의권 상실", "수임제한 위반 소송행위도 상대방이 알았거나 알 수 있었는데 사실심 변론종결까지 이의하지 않으면 소송법상 완전한 효력이 생길 수 있다.", "수임제한 위반 소송행위는 상대방이 이의하지 않아도 소송법상 효력이 생기지 않는다.", "민사소송법, 판례", "이의권"),
    spec(16, "조정위원 취급 사건", "변호사가 조정위원으로 취급한 사건은 의뢰인과 상대방이 모두 동의하여도 수임할 수 없다.", "변호사가 조정위원으로 취급한 사건도 의뢰인과 상대방이 모두 동의하면 수임할 수 있다.", "변호사법 제31조", "조정위원"),

    spec(17, "성실의무 근거", "변호사의 의뢰인에 대한 성실의무는 이익충돌회피의무의 근거가 된다.", "변호사의 성실의무는 이익충돌회피의무와 무관하다.", "변호사윤리장전", "성실의무"),
    spec(17, "비밀유지 근거", "변호사의 비밀유지의무도 이익충돌회피의무의 근거가 된다.", "변호사의 비밀유지의무는 이익충돌회피의무의 근거가 되지 않는다.", "변호사윤리장전", "비밀유지"),
    spec(17, "형사 후 민사 상대방", "형사사건에서 피고인을 변호한 변호사가 실질적으로 동일한 쟁점의 민사사건에서 피해자 측 소송대리인이 되는 것은 금지된다.", "형사사건 변호가 종료되면 실질적으로 동일한 쟁점의 민사사건에서도 피해자 측 대리가 허용된다.", "변호사법 제31조, 판례", "실질 동일 사건"),
    spec(17, "동시대리 동의", "동일 사건에서 의뢰인들의 이익이 충돌하면 관계 의뢰인이 모두 동의하더라도 동시대리가 제한될 수 있다.", "동일 사건에서 의뢰인들의 이익이 충돌해도 모두 동의하면 변호사는 둘 이상의 의뢰인을 동시에 대리할 수 있다.", "변호사윤리장전", "동시대리", grade="A+"),

    spec(18, "조정 종결 수권", "변호사는 의뢰인의 구체적인 수권 없이 임의로 조정으로 사건을 종결시킬 수 없다.", "변호사는 소송대리권이 있으면 의뢰인의 구체적인 수권 없이도 조정으로 사건을 종결시킬 수 있다.", "민사소송법", "조정 수권"),
    spec(18, "상대방 대리인 친족", "상대방 대리인과 친족관계가 있으면 이를 알리는 것만으로 충분하지 않고 이해충돌 여부에 따라 수임이 제한될 수 있다.", "상대방 대리인과 친족관계가 있어도 미리 의뢰인에게 알리면 사건을 수임할 수 있다.", "변호사윤리장전", "친족관계"),
    spec(18, "결과 설명의무", "변호사는 수임사건 처리가 종료되면 의뢰인에게 그 결과를 설명하여야 한다.", "수임사건 처리가 종료되면 위임관계가 종료되므로 변호사는 결과를 설명할 의무가 없다.", "변호사윤리장전", "결과 설명"),
    spec(18, "부당 요구 거절", "변호사는 의뢰인의 요청이 변호사 품위를 손상시키거나 의뢰인 이익에 배치된다고 인정하면 이유를 설명하고 따르지 않을 수 있다.", "변호사는 의뢰인의 요청이 품위를 손상시키거나 의뢰인 이익에 배치되어도 위임관계가 있으면 따라야 한다.", "변호사윤리장전", "요청 거절", grade="A+"),

    spec(19, "형식적 채권양수", "비변호사가 금품을 받고 형식적으로 채권을 양수하여 경매신청 등 법률사무를 처리하면 변호사법 위반이 될 수 있다.", "비변호사가 형식적으로 채권을 양수한 뒤 자기 명의로 경매신청을 하면 금품을 받아도 변호사법 위반이 아니다.", "변호사법 제109조", "형식 양수"),
    spec(19, "경매입찰 사실상 대리", "비변호사가 경매절차 전 과정에 관여하여 사실상 경매입찰을 대리하고 수수료를 받으면 변호사법 위반이 될 수 있다.", "비변호사가 경매입찰을 사실상 대리하여도 법무사 사무실 직원이면 수수료를 받을 수 있다.", "변호사법 제109조", "경매 대리"),
    spec(19, "소송서류 작성 주도", "비변호사가 실질적으로 사건 처리를 주도하고 소송서류를 작성해 주며 대가를 받으면 금액이 적어도 변호사법 위반이 될 수 있다.", "비변호사가 소송서류 작성을 주도해도 받은 돈이 통상 변호사보수보다 적고 당사자가 직접 소송행위를 하면 변호사법 위반이 아니다.", "변호사법 제109조", "소액 대가"),
    spec(19, "공무원 선처 금품", "경찰관이 담당 업무 과정에서 선처 부탁과 금품을 받은 행위는 변호사법 위반이 아니라 다른 형사책임이 문제될 수 있다.", "경찰관이 사건 선처 부탁과 금품을 받은 행위는 비변호사의 법률사무 취급으로 변호사법 위반이다.", "변호사법 제109조, 형법", "공무원 금품", grade="A+"),

    spec(20, "의무 발생 시점", "변호사의 의뢰인에 대한 의무는 선임을 승낙하여 위임관계가 성립한 때부터 발생하고 보수 일부 지급 시점부터만 발생하는 것은 아니다.", "변호사의 의뢰인에 대한 의무는 선임 승낙 시가 아니라 착수금 등 보수 일부를 지급받은 때부터 발생한다.", "민법, 변호사윤리장전", "선임 승낙"),
    spec(20, "의뢰인 지휘감독", "변호사는 위임사무를 선관주의로 처리하지만 독립 전문직으로서 의뢰인의 지휘·감독을 받는 것은 아니다.", "변호사는 위임관계에 있으므로 의뢰인의 지휘·감독을 받는다.", "변호사윤리장전", "독립성"),
    spec(20, "위임종료 후 의무", "심급대리 사건이 종료되어도 정산, 비밀유지, 설명 등 일부 권리·의무는 남을 수 있다.", "심급대리 원칙상 판결서를 송달받아 설명하면 의뢰인에 대한 모든 권리·의무가 소멸된다.", "민법, 변호사윤리장전", "종료 후 의무"),
    spec(20, "위임계약 해지", "변호사는 의뢰인 동의 없이 위임계약을 해지할 수 있으나 부득이한 사유 없이 불리한 시기에 해지하면 손해를 배상하여야 한다.", "변호사는 의뢰인의 동의가 없으면 위임계약을 해지할 수 없다.", "민법 제689조", "불리한 시기 해지", grade="A+"),

    spec(21, "범죄목적 사건", "변호사는 수임하려는 사건이 의뢰인의 범죄행위를 목적으로 한 사건이면 수임을 거절하여야 한다.", "변호사는 수임하려는 사건이 의뢰인의 범죄행위를 목적으로 하더라도 비밀유지의무 때문에 수임을 거절할 수 없다.", "변호사윤리장전", "범죄목적"),
    spec(21, "부적합 지시 변경권고", "변호사는 의뢰인의 지시가 위임 취지에 맞지 않거나 불리하면 이를 고지하고 지시 변경을 요구 또는 권고할 수 있다.", "변호사는 의뢰인의 지시가 불리하더라도 고지만 할 수 있고 지시 변경을 요구하거나 권고할 수 없다.", "변호사윤리장전", "지시 변경"),
    spec(21, "비용 선급", "의뢰인은 특별한 약정이 없으면 변호사의 청구에 따라 위임사무 처리비용을 선급할 의무를 진다.", "의뢰인은 특별한 약정이 없는 한 변호사가 청구하여도 위임사무 처리비용을 선급할 의무가 없다.", "민법 제687조", "비용 선급"),
    spec(21, "국선의 사선 전환", "국가기관에 의하여 선임된 변호사도 법령과 절차에 반하지 않는 범위에서 의뢰인의 요청에 따라 사선으로 전환될 수 있다.", "국가기관에 의하여 선임된 변호사는 의뢰인의 요청이 있더라도 사선으로 전환해서는 안 된다.", "형사소송법, 변호사윤리장전", "국선 전환", grade="A+"),

    spec(22, "퇴직공직자 업무내역", "퇴직공직자가 법무법인에 취업한 경우 법무법인이 일률적으로 그 명단과 업무내역서를 법조윤리협의회에 제출하여야 하는 것은 아니다.", "퇴직공직자가 법무법인에 취업하면 법무법인은 퇴직공직자 명단과 업무내역서를 법조윤리협의회에 제출하여야 한다.", "변호사법, 법조윤리협의회 규정", "퇴직공직자 명단"),
    spec(22, "공직퇴임변호사 제출기간", "공직퇴임변호사의 수임자료 제출의무 기간은 변호사법상 기준에 따르며 퇴직일부터 2년으로 단정할 수 없다.", "공직퇴임변호사는 퇴직일부터 2년 동안 수임자료와 처리결과를 법조윤리협의회에 제출하여야 한다.", "변호사법", "제출기간"),
    spec(22, "특정변호사 사건목록", "지방변호사회는 변호사법령상 일정 수 이상의 사건을 수임한 특정변호사의 성명과 사건목록을 법조윤리협의회에 제출하여야 한다.", "지방변호사회는 특정변호사의 성명과 사건목록을 법조윤리협의회에 제출할 수 없다.", "변호사법, 법조윤리협의회", "특정변호사", grade="A+"),
    spec(22, "징계개시 신청기관", "공직퇴임변호사의 징계사유를 발견한 지방변호사회는 법조윤리협의회 위원장이 아니라 대한변호사협회에 징계개시를 신청하는 절차가 문제된다.", "지방변호사회는 공직퇴임변호사의 징계사유를 발견하면 법조윤리협의회 위원장에게 징계개시를 신청할 수 있다.", "변호사법", "징계개시 신청"),

    spec(23, "현재 상대방 수임", "법무법인이 현재 사건의 상대방이 위임하는 다른 사건을 수임하려면 기존 의뢰인의 동의 등 요건이 필요할 수 있다.", "법무법인은 현재 사건의 상대방이 위임하는 다른 사건도 기존 의뢰인의 동의 없이 자유롭게 수임할 수 있다.", "변호사법 제31조", "현재 상대방"),
    spec(23, "법무법인 스크리닝", "이해충돌 변호사가 관여하지 않고 그 사유가 사건처리에 영향을 주지 않는 합리적 사유가 없으면 기존 의뢰인의 동의만으로 법무법인 수임제한이 해소되지 않을 수 있다.", "이해충돌 변호사가 관여하지 않겠다고 하면 합리적 차단 사유가 없어도 기존 의뢰인의 동의만으로 법무법인은 사건을 수임할 수 있다.", "변호사법 제31조, 변호사윤리장전", "스크리닝", grade="A+"),
    spec(23, "배우자 근무 법무법인", "대립 당사자의 배우자가 법무법인 변호사로 근무해도 관여 배제와 합리적 차단 사유가 있으면 법무법인은 사건을 수임할 수 있다.", "대립 당사자의 배우자가 법무법인 변호사로 근무하면 그 변호사가 관여하지 않아도 법무법인은 사건을 수임할 수 없다.", "변호사윤리장전", "배우자 차단"),
    spec(23, "종전 형사 변호 후 민사", "법무법인이 과거 관련 형사사건에서 한쪽 변호인으로 활동했다면 같은 사고 손해배상청구에서 반대편 사건은 동의를 얻어도 수임할 수 없는 경우가 있다.", "법무법인이 과거 관련 형사사건에서 변호인으로 활동했더라도 종전 의뢰인이 동의하면 같은 사고 손해배상청구에서 반대편 사건을 수임할 수 있다.", "변호사법 제31조", "종전 사건"),

    spec(24, "검사 취급 후 민사", "검사로서 교통사고 형사사건을 처리한 경우 그 사고 관련 손해배상청구사건은 직무상 취급한 사건과 관련되어 수임제한이 문제된다.", "검사로서 교통사고 형사사건을 처리했더라도 민사 손해배상청구사건은 별개이므로 수임할 수 있다.", "변호사법 제31조", "검사 취급"),
    spec(24, "현재 형사변호인 상대 민사", "교통사고 형사사건의 변호인은 의뢰인 동의를 얻어도 같은 사고 피해자의 손해배상청구에서 의뢰인 상대방을 대리할 수 없다.", "교통사고 형사사건의 변호인은 의뢰인 동의가 있으면 같은 사고 피해자의 손해배상청구에서 의뢰인 상대방을 대리할 수 있다.", "변호사법 제31조", "현재 의뢰인"),
    spec(24, "종전 형사 종료 후 민사", "교통사고 형사사건 변호가 종료된 뒤에도 같은 사고 손해배상청구에서 피해자 측을 대리하는 것은 수임제한이 문제될 수 있다.", "교통사고 형사사건 변호가 종료되면 같은 사고 손해배상청구에서 피해자 측을 대리할 수 있다.", "변호사법 제31조", "종전 형사", grade="A+"),
    spec(24, "공동피고 대리", "손해배상청구에서 공동피고 사이 이해가 대립되면 모두 동의하더라도 같은 변호사가 공동으로 대리할 수 없다.", "손해배상청구에서 공동피고 사이 이해가 대립되어도 모두 동의하면 같은 변호사가 공동으로 대리할 수 있다.", "변호사윤리장전", "공동피고"),

    spec(25, "검사의 변호인 추천", "검사가 피의자에게 자신의 선배 변호사를 선임해 보라고 권유하는 것은 검사윤리에 위배될 수 있다.", "검사가 피의자의 방어권 보장을 위해 자신의 선배 변호사를 선임해 보라고 권유하는 것은 검사윤리에 위배되지 않는다.", "검사윤리강령", "변호인 추천"),
    spec(25, "검사 직함 공표 승인", "검사가 직무 관련 수사내용을 검사 직함을 사용하여 공표하려면 소속 기관장 신고 등 법정 절차를 따라야 하고 검찰총장 승인만이 유일한 요건은 아니다.", "검사가 사회적으로 주목받는 수사내용을 검사 직함으로 공표하려면 반드시 검찰총장의 승인을 받아야만 한다.", "검사윤리강령", "공표 절차", grade="A+"),
    spec(25, "법관과 대리인 골프", "법관은 담당 사건의 변호인이나 대리인과 사건 이야기를 하지 않더라도 사적 골프 등 교류를 삼가야 한다.", "법관은 담당 사건의 변호인과 사건 관련 이야기를 하지 않으면 함께 골프를 쳐도 된다.", "법관윤리강령", "사적 교류"),
    spec(25, "피해자 사례품", "검사는 사건 피해자로부터 감사 표시 명목의 소액 물품도 받아서는 안 된다.", "검사는 피해자가 감사 표시로 제공하는 소액 음료수 세트 정도는 받을 수 있다.", "검사윤리강령", "소액 금품"),

    spec(26, "공동사건처리 등록", "외국법자문법률사무소가 국내 법무법인과 혼재 사건을 공동 처리하고 수익을 분배하려면 사전 등록 등 법정 요건을 갖추어야 한다.", "외국법자문법률사무소는 5년 이상 본점사무소가 있으면 사전 등록 없이 국내 법무법인과 혼재 사건을 공동 처리하고 수익을 분배할 수 있다.", "외국법자문사법", "공동사건처리"),
    spec(26, "자격승인 경력", "외국변호사 자격 취득 후 원자격국 법률사무 경력 요건은 국내 법무법인에서의 조사·연구 경력만으로 충족되지 않을 수 있다.", "외국변호사 자격 취득 후 국내 법무법인에서 원자격국 법 조사·연구를 수행한 기간은 외국법자문사 자격승인 경력으로 충분하다.", "외국법자문사법", "직무경력"),
    spec(26, "본점 5년 운영", "외국법자문법률사무소 설립인가를 받으려면 본점사무소가 당사국 법률에 따라 적법하게 설립되어 5년 이상 정상적으로 운영되었어야 한다.", "외국법자문법률사무소 설립인가는 본점사무소 설립 후 정상운영 기간과 관계없이 외국변호사 자격만 있으면 받을 수 있다.", "외국법자문사법", "본점 5년", grade="A+"),
    spec(26, "등록 신청 기산점", "외국법자문법률사무소 등록신청 기간은 설립인가통지일이 아니라 설립인가 고시 등 법정 기산점에 따라 판단한다.", "외국법자문법률사무소를 운영하려면 법무부장관의 설립인가통지를 받은 날부터 3개월 이내에 대한변호사협회에 등록신청하여야 한다.", "외국법자문사법", "등록 기산점"),

    spec(27, "부동산 중개", "부동산 중개는 법률문제가 발생할 수 있다는 이유만으로 당연히 변호사의 업무에 포함되지 않는다.", "부동산 중개는 법률문제가 발생되는 행위이므로 당연히 변호사의 업무에 포함된다.", "변호사법, 공인중개사법", "부동산 중개"),
    spec(27, "변리사 등록", "변호사는 특허 관련 법률사무를 할 수 있으나 변리사로서 업무를 하려면 변리사 등록을 하고 변리사회에 가입하여야 한다.", "변호사는 변리사 등록을 하지 않아도 변리사로서의 업무를 수행할 수 있다.", "변리사법", "변리사 등록", grade="A+"),
    spec(27, "세무대리", "세무대리업무도 법률사무의 성격을 가질 수 있어 변호사의 업무와 관련될 수 있다.", "세무대리업무는 법률사무가 아니므로 변호사의 업무에 포함되지 않는다.", "변호사법, 세무사법", "세무대리"),
    spec(27, "변리사의 소송대리", "변리사에게 지식재산권 사건 관련 업무가 인정되더라도 변호사가 아닌 변리사가 특허침해 손해배상청구소송을 일반적으로 대리할 수는 없다.", "변리사는 변호사가 아니어도 특허침해 손해배상청구소송을 대리할 수 있다.", "민사소송법, 변리사법", "소송대리"),

    spec(28, "직권 징계개시", "대한변호사협회 변호사징계위원회는 법정 청구 외에도 일정한 경우 직권으로 징계절차를 개시할 수 있다.", "대한변호사협회 변호사징계위원회는 기관장의 징계개시 청구가 있어야만 징계절차를 개시할 수 있다.", "변호사법", "직권개시"),
    spec(28, "징계처분 보고", "대한변호사협회장은 확정된 징계처분을 공개·통지할 뿐 아니라 법무부장관에게 보고하여야 한다.", "대한변호사협회장은 확정된 징계처분을 공개·통지하면 충분하고 법무부장관에게 보고할 필요는 없다.", "변호사법", "법무부 보고"),
    spec(28, "불출석 서면심의", "징계혐의자가 출석명령을 받고도 징계심의기일에 출석하지 않으면 징계위원회는 서면으로 심의절차를 진행할 수 있다.", "징계혐의자가 징계심의기일에 출석하지 않으면 징계위원회는 반드시 기일을 다시 지정하여야 하고 서면심의를 할 수 없다.", "변호사법", "서면심의", grade="A+"),
    spec(28, "징계 효력 발생", "대한변호사협회 징계위원회의 징계 효력은 이의신청 기간 경과 방식이 아니라 변호사법상 통지와 불복절차에 따라 발생한다.", "대한변호사협회 징계위원회의 징계 효력은 30일 이내 이의신청을 하지 않으면 그 다음 날부터 발생한다.", "변호사법", "효력 발생"),

    spec(29, "징계 종류", "변호사 징계의 종류에는 영구제명, 제명, 3년 이하 정직, 3천만 원 이하 과태료, 견책이 포함된다.", "변호사 징계의 종류에는 영구제명, 제명, 3년 이하 정직, 5천만 원 이하 과태료, 견책이 포함된다.", "변호사법", "과태료 상한"),
    spec(29, "영구제명 사유", "변호사 직무와 관련하여 2회 이상 금고 이상의 형이 확정된 경우 영구제명 사유가 될 수 있으며 집행유예와 과실범 제외 여부는 법정 요건에 따른다.", "변호사 직무 관련 2회 이상 금고 이상의 형이 확정되어도 집행유예와 과실범이면 항상 영구제명 사유에서 제외된다.", "변호사법", "영구제명"),
    spec(29, "징계개시 청구권자", "대한변호사협회 징계위원회에 징계개시를 청구할 수 있는 자에는 지방검찰청 검사장만이 아니라 법무부장관 등 법정 청구권자가 포함된다.", "징계개시 청구권자는 지방검찰청 검사장, 지방변호사회장, 법조윤리협의회 위원장으로 한정된다.", "변호사법", "청구권자"),
    spec(29, "업무정지명령 해제", "법무부장관은 업무정지명령의 필요성이 없어졌다고 볼 상당한 이유가 있으면 직권으로 그 명령을 해제할 수 있다.", "법무부장관은 업무정지명령을 한 뒤에는 공판이나 징계 절차가 끝날 때까지 직권으로 해제할 수 없다.", "변호사법", "업무정지 해제", grade="A+"),

    spec(30, "군법무관 수임제한", "장기복무 군법무관 출신 변호사는 퇴직 전 근무한 군사법원이 처리하는 사건을 퇴직 후 법정기간 동안 수임할 수 없다.", "장기복무 군법무관 출신 변호사는 군사법원 사건에 관하여 공직퇴임변호사 수임제한을 받지 않는다.", "변호사법 제31조의2", "군사법원"),
    spec(30, "사돈 사건 예외", "퇴직 법관의 수임제한 예외는 법정 친족 범위에 따라 판단되며 사돈이라는 사정만으로 수임제한이 해제되지 않는다.", "퇴직 법관은 퇴직 후 1년이 지나지 않아도 사돈의 사건은 수임할 수 있다.", "변호사법 제31조의2", "친족 예외", grade="A+"),
    spec(30, "검사 퇴직 후 법원 사건", "검사로 근무하다 퇴직한 변호사는 퇴직 전 소속 검찰청 사건이 아닌 고등법원 처리 사건은 수임할 수 있다.", "검사로 근무하다 퇴직한 변호사는 같은 지역 고등법원이 처리하는 사건도 퇴직 후 1년 동안 수임할 수 없다.", "변호사법 제31조의2", "기관 범위"),
    spec(30, "법무법인 담당 지정", "법무법인은 퇴직 법관을 구성원으로 영입할 수 있으나 퇴직 후 법정기간 동안 퇴직 전 소속 법원 사건 담당변호사로 지정할 수 없다.", "법무법인은 퇴직 법관을 구성원으로 영입하면 퇴직 전 소속 법원 사건 담당변호사로 지정할 수 있다.", "변호사법 제31조의2", "담당 지정"),

    spec(31, "무죄변론", "피고인이 범행을 인정하더라도 수사기관에 물증이 없음을 이유로 법률상 허용되는 범위의 무죄변론을 하는 것 자체가 곧바로 변호사윤리 위반은 아니다.", "피고인이 범행을 인정하면 변호인이 무죄변론을 하는 것은 언제나 변호사윤리 위반이다.", "형사소송법, 변호사윤리장전", "무죄변론", grade="A+"),
    spec(31, "증거폐기 도움", "변호인이 제3자에게 연락하여 절취물 등 물증 폐기를 돕는 행위는 변호사윤리 위반이다.", "변호인이 의뢰인의 방어를 위해 제3자에게 연락하여 물증 폐기를 도와도 된다.", "형법, 변호사윤리장전", "증거폐기"),
    spec(31, "형사책임 설명", "변호인이 의뢰인에게 증거인멸죄 성립 범위 등 법률효과를 설명하는 것은 허용될 수 있다.", "변호인이 의뢰인에게 증거인멸죄 성립 범위를 설명하는 것은 증거인멸 조언으로 언제나 변호사윤리 위반이다.", "형법, 변호사윤리장전", "법률 설명"),
    spec(31, "사임", "변호인이 양심상 의뢰인의 부당한 요청을 따를 수 없으면 사임할 수 있다.", "변호인은 의뢰인의 요청이 부당하더라도 일단 수임한 이상 사임할 수 없다.", "변호사윤리장전", "사임"),

    spec(32, "연수 구분", "변호사 연수는 일반연수와 특별연수로 구분되고 특별연수에는 자체연수, 위임연수, 위탁연수, 인정연수 등이 있다.", "변호사 연수는 일반연수와 특별연수로만 구분되고 특별연수의 세부 유형은 인정되지 않는다.", "변호사연수규칙", "연수 유형"),
    spec(32, "의무연수 구분", "의무연수는 의무전문연수와 의무윤리연수로 나뉘며 현장연수를 원칙으로 한다.", "의무연수는 의무전문연수와 의무윤리연수로 나뉘지 않고 온라인 연수를 원칙으로 한다.", "변호사연수규칙", "의무연수"),
    spec(32, "인정연수 계획", "인정연수 지정을 받으려는 학술단체는 출석관리 등 연수관리계획을 연수 실시 전 법정기한까지 제출하여야 한다.", "인정연수 지정을 받으려는 학술단체는 연수 실시 후 출석관리 계획을 제출할 수 있다.", "변호사연수규칙", "인정연수"),
    spec(32, "의무윤리연수 시간", "의무윤리연수 이수시간 기준은 1년 2시간이 아니라 변호사연수규칙상 별도 기준에 따라 계산된다.", "의무윤리연수 이수시간은 1년 2시간을 기준으로 연수주기에 맞추어 비례 계산한다.", "변호사연수규칙", "윤리연수 시간", grade="A+"),

    spec(33, "공익활동 시간", "변호사의 공익활동 의무시간은 연간 40시간이 아니라 대한변호사협회 및 지방변호사회 규정의 기준에 따른다.", "변호사는 연간 40시간 이상 공익활동을 해야 한다.", "변호사 공익활동 규정", "40시간"),
    spec(33, "저렴한 비용 공익활동", "공익단체에 상당히 저렴한 비용으로 법률서비스를 제공하는 경우도 규정상 공익활동으로 인정될 수 있다.", "공익단체에 법률서비스를 제공하더라도 조금이라도 비용을 받으면 공익활동으로 인정되지 않는다.", "변호사 공익활동 규정", "저렴한 비용"),
    spec(33, "국선대리인", "국선변호인뿐 아니라 국선대리인 활동도 공익활동으로 인정될 수 있다.", "국선변호인 활동은 공익활동이나 국선대리인 활동은 공익활동으로 볼 수 없다.", "변호사 공익활동 규정", "국선대리인"),
    spec(33, "법무법인 공익활동 지정", "법무법인은 구성원과 소속 변호사 전원을 대신하여 공익활동을 수행할 변호사를 지정할 수 있다.", "법무법인은 각 변호사의 공익활동을 대신 수행할 변호사를 지정할 수 없다.", "변호사 공익활동 규정", "지정 변호사", grade="A+"),

    spec(34, "개업 사내변호사 소송대리", "개업신고를 한 사내변호사가 겸직허가를 받으면 소속 회사 사건을 수임하여 소송대리업무를 수행할 수 있다.", "개업신고를 한 사내변호사는 겸직허가를 받아도 소속 회사 사건을 수임하여 소송대리업무를 수행할 수 없다.", "변호사법 겸직 규정", "사내변호사 수임"),
    spec(34, "이사 겸직허가", "개업신고를 한 변호사가 회사 이사로 취임하려면 원칙적으로 소속 지방변호사회의 겸직허가가 필요하다.", "개업신고를 한 변호사는 회사 이사로 취임할 때 소속 지방변호사회 겸직허가가 필요하지 않다.", "변호사법 겸직 규정", "이사 겸직"),
    spec(34, "소속변호사 시간제 사내근무", "법무법인의 구성원 아닌 소속 변호사는 법무법인 소속 지위와 사내변호사 근무를 임의로 병행하기 어렵다.", "법무법인의 구성원 아닌 소속 변호사는 지방변호사회 겸직허가를 받으면 일부 요일은 법무법인, 일부 요일은 회사 사내변호사로 근무할 수 있다.", "변호사법, 변호사윤리장전", "병행 근무", grade="A+"),
    spec(34, "감사 겸직", "개업신고를 한 변호사가 회사 감사로 취임하는 경우에는 겸직허가 없이도 허용될 수 있다.", "개업신고를 한 변호사가 회사 감사로 취임하려면 언제나 소속 지방변호사회 겸직허가가 필요하다.", "변호사법 겸직 규정", "감사"),

    spec(35, "사내변호사 독립성과 비밀", "개업신고를 한 사내변호사도 변호사로서 독립성을 유지하고 비밀유지의무를 준수하여야 한다.", "사내변호사는 회사 소속이므로 변호사로서 독립성과 비밀유지의무를 부담하지 않는다.", "변호사윤리장전", "독립성"),
    spec(35, "사용자 고객 사건", "사내변호사가 사용자의 지시나 방침에 따라 사용자의 고객이나 제3자의 사건을 수임하는 것은 허용되지 않는다.", "사내변호사는 사용자의 지시가 있으면 사용자의 고객이나 제3자의 사건을 수임할 수 있다.", "변호사법", "제3자 사건"),
    spec(35, "회사 유료회원 답변", "영리회사가 고용한 변호사가 회사 유료회원의 법률질문에 변호사 명의로 답변하는 것은 변호사법에 위반될 수 있다.", "영리회사가 고용한 변호사가 회사 유료회원의 법률질문에 변호사 명의로 답변하는 것은 허용된다.", "변호사법 제34조", "유료회원 답변"),
    spec(35, "회사 명의 답변", "영리회사가 고용 변호사를 통해 유료회원 법률질문에 회사 명의로 답변하는 것도 변호사법에 위반될 수 있다.", "영리회사가 고용 변호사를 통해 유료회원 법률질문에 회사 명의로 답변하면 변호사법에 위반되지 않는다.", "변호사법 제34조", "회사 명의", grade="A+"),

    spec(36, "뇌물제공 가담", "사내변호사는 회사의 이익을 이유로 담당 공무원에게 뇌물을 제공하는 범죄행위에 가담할 수 없다.", "사내변호사는 회사의 이익을 위하여 성실히 업무를 수행해야 하므로 담당 공무원에게 뇌물을 제공할 수 있다.", "변호사윤리장전, 형법", "뇌물 가담"),
    spec(36, "즉시 외부공개", "사내변호사는 회사 임원의 법 위반 사실을 발견하였다는 이유만으로 즉시 수사기관 통보나 언론 공개를 하여야 하는 것은 아니다.", "사내변호사는 회사 임원의 법 위반 사실을 발견하면 즉시 수사기관에 통보하거나 언론에 공개하여야 한다.", "변호사윤리장전", "외부공개"),
    spec(36, "범죄 은폐 조언", "사내변호사는 회사 임원의 범죄행위가 드러나지 않도록 법적 조언을 해서는 안 된다.", "사내변호사는 범죄행위에 직접 가담하지 않으면 범죄행위가 드러나지 않도록 법적 조언을 할 수 있다.", "변호사윤리장전", "은폐 조언"),
    spec(36, "상급기관 보고 후 사직", "사내변호사는 위법행위를 회사 내부의 적절한 기관에 알린 뒤 아무 조치가 없으면 사직할 수 있다.", "사내변호사는 회사 내부에 위법행위를 알려도 조치가 없으면 계속 근무해야 하고 사직할 수 없다.", "변호사윤리장전", "사직", grade="A+"),

    spec(37, "위증 교사 금지", "변호사는 위증 교사나 허위증거 제출을 하게 해서는 안 되고 그러한 의심을 받을 행위도 하지 않아야 한다.", "변호사는 의뢰인 방어를 위해 허위증거 제출의 의심을 받을 행위 정도는 할 수 있다.", "변호사윤리장전", "위증 교사"),
    spec(37, "진술거부권 권고", "형사변호인이 피고인이나 피의자에게 진술거부권을 알려 주고 그 행사를 권고하는 것은 진실의무에 위배되지 않는다.", "형사변호인이 피고인이나 피의자에게 진술거부권을 알려 주고 행사를 권고하면 진실의무에 위배될 수 있다.", "헌법, 형사소송법", "진술거부권", grade="A+"),
    spec(37, "정당한 이익", "형사변호인의 임무가 피고인 보호라 하더라도 보호되는 이익은 법적으로 보호받을 가치가 있는 정당한 이익으로 제한된다.", "형사변호인은 피고인 보호를 위해 법적으로 보호받을 가치가 없는 이익까지 대변할 수 있다.", "변호사윤리장전", "정당한 이익"),
    spec(37, "비난 정도와 수임거절", "피고인의 범행에 대한 사회 일반의 비난 정도가 강하다는 이유만으로 변호사가 수임을 거절할 수 없다.", "피고인의 범행에 대한 사회 일반의 비난 정도가 강하면 변호사는 그 이유만으로 수임을 거절할 수 있다.", "변호사윤리장전", "수임거절"),

    spec(38, "사무직원 통한 접촉", "변호사가 직접 접촉할 수 없는 대리인 있는 상대방을 사무직원을 시켜 접촉하게 하는 것도 허용되지 않는다.", "변호사는 대리인 있는 상대방을 직접 접촉할 수 없지만 사무직원을 시켜 접촉하는 것은 허용된다.", "변호사윤리장전", "사무직원 접촉"),
    spec(38, "의뢰인 직접 교섭", "변호사를 선임한 의뢰인은 상대방 당사자를 직접 접촉하거나 교섭할 수 있다.", "변호사를 선임한 의뢰인은 상대방 당사자와 직접 접촉하거나 교섭할 수 없다.", "변호사윤리장전", "의뢰인 교섭", grade="A+"),
    spec(38, "법인 임직원 접촉", "상대방이 법인인 경우에도 변호사가 모든 전·현직 임직원과 직접 접촉하거나 교섭할 수 없는 것은 아니다.", "상대방이 법인이면 변호사는 법인의 전·현직 임직원 누구와도 직접 접촉하거나 교섭할 수 없다.", "변호사윤리장전", "법인 임직원"),
    spec(38, "의뢰인 동의만으로 접촉", "대리인 있는 상대방과의 직접 접촉은 의뢰인 동의만으로 허용되지 않고 상대방 대리인의 동의 등 요건이 필요하다.", "대리인 있는 상대방도 의뢰인이 동의하면 변호사가 직접 접촉하거나 교섭할 수 있다.", "변호사윤리장전", "의뢰인 동의"),

    spec(39, "수임정보 공유", "법무법인은 수임제한 확인을 위해 의뢰인, 상대방, 사건명 등 수임정보를 관리하고 필요한 범위에서 구성원 변호사들이 공유할 수 있도록 조치하여야 한다.", "법무법인의 사건 수임정보는 개인정보이므로 최초 상담자 아닌 구성원 변호사들이 공유할 수 없도록 하여야 한다.", "변호사윤리장전", "수임정보 공유", grade="A+"),
    spec(39, "퇴직 소속변호사 수임제한", "법무법인의 구성원이었거나 소속 변호사였던 사람은 소속 기간 중 그 법인이 상의를 받아 수임을 승낙한 사건에 관하여 업무를 수행할 수 없다.", "법무법인 소속을 떠난 변호사는 소속 기간 중 법인이 수임한 사건이라도 자유롭게 업무를 수행할 수 있다.", "변호사법 제31조", "퇴직 후 제한"),
