def make_items() -> list[dict]:
    items = []
    per_q_seen: dict[int, int] = {}
    for row in SPECS:
        q = row["q"]
        per_q_seen[q] = per_q_seen.get(q, 0) + 1
        part = per_q_seen[q]
        why = f"{row['topic']}에 관한 최소 원리 atom입니다. {DATE} 시행 법령과 제9회 법조윤리시험 정답 기준으로 정리했습니다."
        items.append({
            "src": [SRC],
            "years": [SRC],
            "freq": 1,
            "hot": False,
            "ids": [q],
            "xref": [],
            "subject": SUBJECT,
            "sourceQuestionId": f"legal_ethics_r9_q{q:02d}",
            "sourcePart": str(part),
            "curation": {"status": "manual_curated", "date": DATE, "note": "사례 인물과 복합 사실관계를 제거하고 최소 법리 atom으로 재작성함."},
            "pid": f"legal-ethics-r9-q{q:02d}-{part:02d}",
            "art": row["ref"].split(",")[0],
            "artNo": None,
            "topic": row["topic"],
            "rep": row["rep"],
            "a": "O",
            "why": why,
            "ref": row["ref"],
            "grade": row["grade"],
            "weight": row["weight"],
            "twins": [{
                "q": row["twin"],
                "trap": row["trap"],
                "why": why,
                "corrected": row["rep"],
                "src": [SRC],
                "weight": row["weight"],
                "grade": row["grade"],
                "ref": row["ref"],
                "sourcePart": str(part),
            }],
        })
    return items


def validate(data: dict) -> None:
    items = data["items"]
    if data["count"] != len(items):
        raise ValueError("count mismatch")
    per_q = {q: 0 for q in range(1, 41)}
    forbidden = ["甲", "乙", "丙", "丁", "戊", "己", " 이 사례", "이 사례는", " 위 사안", "위 사안은"]
    ascii_name = re.compile(r"(?<![A-Z])[A-D](?![A-Z])")
    for item in items:
        for q in item["ids"]:
            per_q[q] += 1
        texts = [item["rep"], item["why"], item["ref"]]
        for twin in item.get("twins", []):
            texts.extend([twin.get("q", ""), twin.get("why", ""), twin.get("corrected", "")])
        for text in texts:
            if any(token in text for token in forbidden):
                raise ValueError(f"forbidden token in {item['pid']}: {text}")
            if ascii_name.search(text):
                raise ValueError(f"case person token in {item['pid']}: {text}")
            if "?" in text:
                raise ValueError(f"question mark in {item['pid']}: {text}")
        if not item["rep"].endswith("."):
            raise ValueError(f"representative is not a sentence: {item['pid']}")
        for twin in item.get("twins", []):
            if not twin.get("q", "").endswith("."):
                raise ValueError(f"twin is not a sentence: {item['pid']}")
    bad = {q: n for q, n in per_q.items() if n != 4}
    if bad:
        raise ValueError(f"expected 4 atoms per question: {bad}")


def main() -> int:
    items = make_items()
    data = {
        "title": "법조윤리 제9회 OX atom",
        "version": "2026-06-17.exam9.manual.v1",
        "source": "제9회 법조윤리시험 공식 문제 및 확정정답",
        "lawAsOf": DATE,
        "subject": SUBJECT,
        "round": 9,
        "count": len(items),
        "items": items,
    }
    validate(data)
    OUT_JSON.write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    print(json.dumps({"status": "ok", "items": len(items), "questions": 40}, ensure_ascii=False))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
